/*
 * LPC2148 SmartX Board - UART0 Hello World
 * Sends "Hello LPC2148" to the Serial Monitor.
 * Uses register-level UART0 at 9600 baud.
 */

#include <LPC214x.h>

void UART0_Init(unsigned int baud) {
    unsigned int divisor = 15000000 / (16 * baud);
    PINSEL0 |= (1 << 1);
    PINSEL0 &= ~(1 << 2);
    PINSEL0 |= (1 << 7);
    PINSEL0 &= ~(1 << 6);
    U0LCR = 0x83;
    U0DLL = divisor & 0xFF;
    U0DLM = (divisor >> 8) & 0xFF;
    U0LCR = 0x03;
    U0FCR = 0x07;
}

void UART0_SendChar(unsigned char ch) {
    while (!(U0LSR & 0x20));
    U0THR = ch;
}

void UART0_SendString(unsigned char *str) {
    unsigned int i = 0;
    while (str[i] != 0) {
        UART0_SendChar(str[i]);
        i++;
    }
}

int main(void) {
    unsigned char msg[] = {'H','e','l','l','o',' ','L','P','C','2','1','4','8','\r','\n',0};
    UART0_Init(9600);
    UART0_SendString(msg);
    while (1) {
        if (U0LSR & 0x01) {
            unsigned char ch = U0RBR;
            UART0_SendChar(ch);
        }
        delay_ms(10);
    }
}
